import React from 'react';
import { Send, Paperclip, Image } from 'lucide-react';
import './Dashboard.css';
import Navbar from '../Components/Navbar';
import Sidebar from '../Components/Sidebar';
import dashboardArrow from '../assets/dashboaredarrow.svg';
import gridIcon from '../assets/Grid.svg';
import microphoneIcon from '../assets/Microphone.svg';
import apitestingIcon from '../assets/apitestingicons.svg';
import guitestingIcon from '../assets/guitestingIcon.svg';

const Dashboard = () => {
  const features = {
    'API Testing Agent': [
      'Generate the test cases for on-boarding flow',
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file'
    ],
    'GUI Testing Agent': [
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file'
    ]
  };

  const FeatureCard = ({ text }) => (
    <div className="feature-card">
      <span className="feature-text">{text}</span>
      <img src={dashboardArrow} alt="arrow" className="arrow-icon" />
    </div>
  );

  return (
    <div className="dashboard-container">
      <Navbar />
      <div className="main-content">
        <Sidebar />
        <div className="chatbot-dashboard">
          <div className="header">
            <h1 className="main-title">
              Unveiling the Power of Test Case Generation
              <br />
              and Execution
            </h1>
            <p className="subtitle">
              Software testing with automated case generation, execution, and meticulous scrutiny, ensuring precision and efficiency in development workflows.
            </p>
          </div>

          <div className="features-section">
            <h2 className="features-title">Try out our Features</h2>
            <div className="features-grid">
              {Object.entries(features).map(([category, items]) => (
                <div 
                  key={category} 
                  className={`feature-category-card ${
                    category === 'API Testing Agent' ? 'api-testing' : 'gui-testing'
                  }`}
                >
                  <div className="category-header">
                    <img 
                      src={category === 'API Testing Agent' ? apitestingIcon : guitestingIcon} 
                      alt={category}
                      className="category-icon"
                    />
                    <h3 className="category-title">{category}</h3>
                  </div>
                  {items.map((item, index) => (
                    <FeatureCard key={index} text={item} />
                  ))}
                </div>
              ))}
            </div>
          </div>

          <div className="input-section">
            <div className="input-container">
              <div className="input-field">
                <input
                  type="text"
                  placeholder="Generate 10 email and password in CSV format"
                  className="main-input"
                />
              </div>
              <div className="action-buttons">
                <button className="icon-button">
                  <Paperclip size={20} />
                </button>
                <button className="icon-button">
                  <Image size={20} />
                </button>
                <button className="icon-button">
                  <img src={gridIcon} alt="grid" width={20} height={20} />
                </button>
                <button className="icon-button">
                  <img src={microphoneIcon} alt="microphone" width={20} height={20} />
                </button>
                <button className="action-send-button">
                  <Send size={16} />
                  Send
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
